"""Reviewed existing-lineage return preparation, no provider or worker dispatch."""
import copy,datetime,hashlib,importlib.util,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
s=importlib.util.spec_from_file_location('a',ROOT/'scripts/engine-browser-adapter.py');a=importlib.util.module_from_spec(s);s.loader.exec_module(a)
def prepare():
 r=ROOT/'target/v2-tsr-return-preparation';src=ROOT/'target/browser-game-session-live10';c=a.d.Native(r/'native')
 def save(n,v):(r/n).write_text(json.dumps(v,indent=2)+'\n')
 rec=a.load('rec','engine-browser-recovery.py');source_tree=rec.tree(src/'native');obs=json.loads((src/'independent-browser/observations.json').read_text());req=c.request();comp=c.cli('project','acceptance','status')
 files={f['path']:f['source'] for f in req['coding']['files'] if f['editable']}
 assert obs['source']=={p:hashlib.sha256(t.encode()).hexdigest() for p,t in files.items()}
 result=json.loads((src/'independent-browser/result.json').read_text());assert result['returncode']==0 and result['stdout_sha256']==rec.sha(src/'independent-browser/stdout.json')
 assert len(obs['checks'])==16 and all(x['pass'] for x in obs['checks'])
 review={'snapshot':comp['snapshot'],'requirements_revision':comp['requirements_revision'],'test_receipt':comp['test_receipt'],'decision':'unresolved','evidence':{'understandable_play':{'met':True,'evidence':'Independent 16-check gameplay assessment: visible controls, maze movement, falling-piece controls, reachable segment clearing, repeated restart restoring193 collectibles and3 lives. Virtual-clock keyboard/click observations; no injected game state. Bounded functional evidence only.'},'engaging_challenge':{'met':False,'evidence':'Unknown: shared maze/falling-block interactions were observed, but balance, complete-maze victory and player satisfaction were not established. Passing functional checks do not establish engaging challenge.'}}}
 save('independent-review.json',review);save('assessment-attribution.json',{'assessor':'independent-agent:/root/harness_audit','transcription':'operator transcribes independent assessment; not model-generated preference or final acceptance','observations_sha256':rec.sha(src/'independent-browser/observations.json'),'execution_result_sha256':rec.sha(src/'independent-browser/result.json')})
 c.json_cli(('project','acceptance','review'),review)
 q=c.request();v=c.cli('project','cycle','request');assert v['branch']=='reconsider',v
 old=json.loads((src/'adapter-admission.json').read_text());public=copy.deepcopy(old['origin']['public']);inputs=q['coding']['relational']['inputs'];assert inputs['parents']==old['origin']['public']['parents']
 public.update(source_snapshots=[q['coding']['snapshot']],public_returns=[a.e.sha(x) for x in inputs['returns']],public_relationships=[a.e.sha(x) for x in q['coding']['relational']['history']])
 public['public_brief']+=' This continuation receives new independent gameplay evidence on the exact current source. Retain the original wants and history; do not treat old defect assertions as new player preference. Consider what, if anything, this evidence changes. Unchanged meaning, abstention, further verification or justified changes are legitimate. Do not force novelty or claim player satisfaction.'
 assessment='Independent gameplay test findings, not player testimony: all16 checks passed on the exact source. The old guidance statements that clearing is unreachable and restart loses collectibles describe an earlier version and are resolved for the tested current version. '+json.dumps({'source':obs['source'],'checks':[{'name':x['name'],'pass':x['pass']} for x in obs['checks']],'concrete_observations':'Start,E,Space,Space,Space clears a lane segment through player controls; repeated restart restores193 collectibles,3 lives and removes placedblocks; pursuit actually reduces lives; restart then restores them.','limitations':'Playwright virtual clock; read-onlycanvas observation. Open-lane-segment clears, not fullTetrisrules. Piece sequence continues acrossrestart; page reload resets it. Balance, complete victory and player satisfaction unknown.','observation_sha256':rec.sha(src/'independent-browser/observations.json')})
 prior={'source_snapshot':q['coding']['snapshot'],'scope':v['scope'],'parents_sha256':a.e.sha(public['parents']),'failed_response_sha256':rec.sha(src/'independent-browser/observations.json'),'assessment':assessment,'attribution':'Independent gameplay checks; independent assessment by /root/harness_audit; operator transcription. Legacy failed_response field binds observation artifact, not failed output.','status':'independent_gameplay_assessment'}
 origin={'directory':str(c.directory),'public':public,'initial_sources':files,'prior_review_feedback':prior};campaign=json.loads((ROOT/'target/tsr-integrated-campaign-1/manifest.json').read_text());expires=(datetime.datetime.now(datetime.timezone.utc)+datetime.timedelta(hours=2)).isoformat()
 ad=a.admission(r/'adapter',origin,c.cli('project','config'),campaign,expires,max_decisions=20,max_executions=8,correction_allowance=4)
 ca={'version':'local-project-cycle@v3','journal':str(r/'cycle'),'scope':v['scope'],'max_decisions':20,'max_executions':8,'local_source_profile':'browser-scoped-source@v1','stage_receipts':'durable-stage-receipts@v1','review_feedback':'attributed-review-feedback@v1','completion_tokens':32768,'input_tokens':a.base.capacity.INPUT_TOKENS,'max_review_rejections':3,'expires_at':expires,'implementation_sha256':a.d.file_sha(Path(a.loop.__file__))}
 save('adapter-admission.json',ad);save('cycle-admission.json',ca);save('after-assessment.json',{'request':q,'view':v});save('source-lineage.json',{'source_native_files':source_tree,'source':str(src),'original_unchanged':rec.tree(src/'native')==source_tree,'parents_unchanged':True,'protected_configuration_unchanged':c.cli('project','config')==a.d.Native(src/'native').cli('project','config')})
 print(json.dumps({'admission_sha256':a.e.sha(ad),'branch':v['branch'],'calls':44,'operations':8,'provider_calls':0},indent=2))
if __name__=='__main__':prepare()
